from decimal import Decimal, ROUND_HALF_UP

def _load_rates():
    with open('config/tax_rates_2025.json', 'r', encoding='utf-8') as f:
        return json.load(f)

_RATES = _load_rates()

def state_tax(state: str, amount: float) -> float:
    """Sales tax owed on amount, using the rate table in config/tax_rates_2025.json."""
    rate = _RATES.get(state.upper(), 0)
    if rate == 0:
        return 0.0
    tax = Decimal(str(amount)) * Decimal(str(rate)) / Decimal('100')
    tax = tax.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return float(tax)

